function monster_footstep(self: EdictT): void {
  if (self.groundentity !== null) self.s.event = KexEntityEventT.EV_OTHER_FOOTSTEP;
}

function M_CheckGib(self: EdictT, mod: ModT): boolean {
  if (self.deadflag) {
    if (mod.id === ModIdT.MOD_CRUSH) return true;
  }
  return self.health <= self.gib_health;
}

/** rogue/g_rogue_monster.cpp:98 */
function monster_done_dodge(self: EdictT): void {
  self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_DODGING;
  if (self.monsterinfo.attack_state === MonsterAttackStateT.AS_SLIDING) {
    self.monsterinfo.attack_state = MonsterAttackStateT.AS_STRAIGHT;
  }
}

function cvarOrDefault(name: string, defaultValue: string): CvarT {
  const c = gi.cvar(name, defaultValue, CvarFlagsT.CVAR_NOFLAGS);
  if (c === null) throw new Error(`gi.cvar(${name}) returned null`);
  return c;
}

/** rogue/g_rogue_newai.cpp:1083-1136. `aimdir`/`aimpoint` collapse into one
 *  destructured return -- see file header. */
function PredictAim(self: EdictT, target: EdictT | null, start: Vec3, bolt_speed: number, eye_height_in: boolean, offset: number): { aimdir: Vec3; aimpoint: Vec3 } {
  if (target === null || !target.inuse) {
    return { aimdir: vec3(0, 0, 0), aimpoint: vec3(0, 0, 0) };
  }

  let eye_height = eye_height_in;
  let dir = vec3_sub(target.s.origin, start);
  if (eye_height) dir[2] += target.viewheight;
  let dist = vec3_length(dir);

  // [Paril-KEX] if our current attempt is blocked, try the opposite one
  const tr = gi.trace(start, null, null, vec3_add(start, dir), self, MASK_PROJECTILE);

  if (tr.ent !== target) {
    eye_height = !eye_height;
    dir = vec3_sub(target.s.origin, start);
    if (eye_height) dir[2] += target.viewheight;
    dist = vec3_length(dir);
  }

  const time = bolt_speed !== 0 ? dist / bolt_speed : 0;

  let vec = vec3_add(target.s.origin, vec3_muls(target.velocity, time - offset));

  // went backwards...
  if (vec3_dot(vec3_normalized(dir), vec3_normalized(vec3_sub(vec, start))) < 0) {
    vec = vec3(target.s.origin[0], target.s.origin[1], target.s.origin[2]);
  } else {
    // if the shot is going to impact a nearby wall from our prediction, just fire it straight.
    if (gi.trace(start, null, null, vec, null, MASK_SOLID).fraction < 0.9) {
      vec = vec3(target.s.origin[0], target.s.origin[1], target.s.origin[2]);
    }
  }

  if (eye_height) vec[2] += target.viewheight;

  return { aimdir: vec3_normalized(vec3_sub(vec, start)), aimpoint: vec };
}

/** rogue/g_rogue_newai.cpp:1292-1299. */
function G_SkillCheck(skills: readonly [number, number, number, number]): boolean {
  const skillInt = Math.trunc(cvarOrDefault("skill", "1").value);
  if (skills.length < skillInt) return true;

  const skill_switch = skills[Math.max(0, Math.min(skills.length - 1, skillInt))] as number;
  return skill_switch === 1.0 ? true : frandom() < skill_switch;
}

const M_CALCPITCH_PITCHES = [-80, -70, -60, -50, -40, -30, -20, -10, -5] as const;

/** rogue/g_rogue_newai.cpp:1140-1203. `aim` is mutated in place on success
 *  (matching the C++ `vec3_t &aim` in/out reference), left untouched on
 *  failure -- see file header. */
function M_CalculatePitchToFire(
  self: EdictT,
  target: Vec3,
  start: Vec3,
  aim: Vec3,
  speed: number,
  time_remaining: number,
  mortar: boolean,
  destroy_on_touch: boolean = false,
): boolean {
  let best_pitch = 0;
  let best_dist = Infinity;

  const sim_time = 0.1;
  const pitched_aim = vectoangles(aim);

  for (const pitch of M_CALCPITCH_PITCHES) {
    if (mortar && pitch >= -30) break;

    pitched_aim[PITCH] = pitch;
    const fwd = AngleVectors_destructured(pitched_aim).forward;

    let velocity = vec3_muls(fwd, speed);
    let origin = vec3(start[0], start[1], start[2]);

    let t = time_remaining;

    while (t > 0) {
      velocity = vec3_add(velocity, vec3_muls(vec3(0, 0, -1), level.gravity * sim_time));

      const end = vec3_add(origin, vec3_muls(velocity, sim_time));
      const tr = gi.trace(origin, null, null, end, null, MASK_SHOT);

      origin = vec3(tr.endpos[0], tr.endpos[1], tr.endpos[2]);

      if (tr.fraction < 1.0) {
        if (tr.surface !== null && (tr.surface.flags & SurfflagsT.SURF_SKY) !== 0) break;

        origin = vec3_add(origin, tr.plane.normal);
        velocity = ClipVelocity(velocity, tr.plane.normal, 1.6);

        const dist = vec3_length(vec3_sub(origin, target)) ** 2;

        if (tr.ent !== null && (tr.ent === self.enemy || tr.ent.client !== null || (tr.plane.normal[2] >= 0.7 && dist < 128 * 128 && dist < best_dist))) {
          best_pitch = pitch;
          best_dist = dist;
        }

        if (destroy_on_touch || (tr.contents & (ContentsT.CONTENTS_MONSTER | ContentsT.CONTENTS_PLAYER | ContentsT.CONTENTS_DEADMONSTER)) !== 0) break;
      }

      t -= sim_time;
    }
  }

  if (Number.isFinite(best_dist)) {
    pitched_aim[PITCH] = best_pitch;
    const fwd = AngleVectors_destructured(pitched_aim).forward;
    aim[0] = fwd[0];
    aim[1] = fwd[1];
    aim[2] = fwd[2];
    return true;
  }

  return false;
}

function monster_duck_down(self: EdictT): void {
  self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_DUCKED;
  self.maxs[2] = self.monsterinfo.base_height - 32;
  self.takedamage = true;
  self.monsterinfo.next_duck_time = Gtime_add(level.time, DUCK_INTERVAL);
  gi.linkentity(self);
}

function monster_duck_hold(self: EdictT): void {
  if (level.time >= self.monsterinfo.duck_wait_time) {
    self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_HOLD_FRAME;
  } else {
    self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_HOLD_FRAME;
  }
}

