export const gunner_die: DieFn = RegisterDie("gunner_die", (self: EdictT, _inflictor: EdictT, _attacker: EdictT, damage: number, _point: Vec3, mod: ModT): void => {
  // check for gib
  if (M_CheckGib(self, mod)) {
    gi.sound(self, SoundchanT.CHAN_VOICE, gi.soundindex("misc/udeath.wav"), 1, ATTN_NORM, 0);

    self.s.skinnum = Math.trunc(self.s.skinnum / 2);

    ThrowGibs(self, damage, [
      { count: 2, gibname: "models/objects/gibs/bone/tris.md2" },
      { count: 2, gibname: "models/objects/gibs/sm_meat/tris.md2" },
      { gibname: "models/monsters/gunner/gibs/chest.md2", type: GibTypeT.GIB_SKINNED },
      { gibname: "models/monsters/gunner/gibs/garm.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_UPRIGHT },
      { gibname: "models/monsters/gunner/gibs/gun.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_UPRIGHT },
      { gibname: "models/monsters/gunner/gibs/foot.md2", type: GibTypeT.GIB_SKINNED },
      { gibname: "models/monsters/gunner/gibs/head.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_HEAD },
    ]);

    self.deadflag = true;
    return;
  }

  if (self.deadflag) return;

  // regular death
  gi.sound(self, SoundchanT.CHAN_VOICE, sound_death.index, 1, ATTN_NORM, 0);
  self.deadflag = true;
  self.takedamage = true;
  M_SetAnimation(self, gunner_move_death, false);
});

