// ---------------------------------------------------------------------------
// chaingun attack
// ---------------------------------------------------------------------------

function gunner_opengun(self: EdictT): void {
  gi.sound(self, SoundchanT.CHAN_VOICE, sound_open.index, 1, ATTN_IDLE, 0);
}

function GunnerFire(self: EdictT): void {
  if (self.enemy === null || !self.enemy.inuse) return;

  const flash_number: MonsterMuzzleflashIdT = MonsterMuzzleflashIdT.MZ2_GUNNER_MACHINEGUN_1 + (self.s.frame - FRAME_attak216);

  const { forward, right } = AngleVectors_destructured(self.s.angles);
  const start = M_ProjectFlashSource(self, monsterFlashOffset()[flash_number] as Vec3, forward, right);
  const { aimdir: aim } = PredictAim(self, self.enemy, start, 0, true, -0.2);
  monster_fire_bullet(self, start, aim, 3, 4, DEFAULT_BULLET_HSPREAD, DEFAULT_BULLET_VSPREAD, flash_number);
}

function gunner_grenade_check(self: EdictT): boolean {
  if (self.enemy === null) return false;

  const start = vec3(0, 0, 0);
  if (!M_CheckClearShot(self, monsterFlashOffset()[MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_1] as Vec3, start)) return false;

  let target: Vec3;
  // check for flag telling us that we're blindfiring
  if ((self.monsterinfo.aiflags & MonsterAiFlagsT.AI_MANUAL_STEERING) !== 0n) {
    target = self.monsterinfo.blind_fire_target;
  } else {
    target = self.enemy.s.origin;
  }

  const dir = vec3_sub(target, start);
  if (vec3_length(dir) < 100) return false;

  const aim = vec3_normalized(dir);
  return M_CalculatePitchToFire(self, target, start, aim, 600, 2.5, false);
}

function GunnerGrenade(self: EdictT): void {
  if (self.enemy === null || !self.enemy.inuse) return;

  const blindfire = (self.monsterinfo.aiflags & MonsterAiFlagsT.AI_MANUAL_STEERING) !== 0n;

  let spread: number;
  let flash_number: MonsterMuzzleflashIdT;

  if (self.s.frame === FRAME_attak105 || self.s.frame === FRAME_attak309) {
    spread = -0.1;
    flash_number = MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_1;
  } else if (self.s.frame === FRAME_attak108 || self.s.frame === FRAME_attak312) {
    spread = -0.05;
    flash_number = MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_2;
  } else if (self.s.frame === FRAME_attak111 || self.s.frame === FRAME_attak315) {
    spread = 0.05;
    flash_number = MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_3;
  } else {
    // (self->s.frame == FRAME_attak114)
    self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_MANUAL_STEERING;
    spread = 0.1;
    flash_number = MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_4;
  }

  if (self.s.frame >= FRAME_attak301 && self.s.frame <= FRAME_attak324) {
    flash_number = MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE2_1 + (MonsterMuzzleflashIdT.MZ2_GUNNER_GRENADE_4 - flash_number);
  }

  // if we're shooting blind and we still can't see our enemy
  let target: Vec3;
  if (blindfire && !visible(self, self.enemy)) {
    if (self.monsterinfo.blind_fire_target[0] === 0 && self.monsterinfo.blind_fire_target[1] === 0 && self.monsterinfo.blind_fire_target[2] === 0) return;
    target = self.monsterinfo.blind_fire_target;
  } else {
    target = self.enemy.s.origin;
  }

  const { forward, right, up } = AngleVectors_destructured(self.s.angles);
  const start = M_ProjectFlashSource(self, monsterFlashOffset()[flash_number] as Vec3, forward, right);

  let pitch = 0;
  {
    const rawAim = vec3_sub(target, self.s.origin);
    const dist = vec3_length(rawAim);
    const aimAdjusted = vec3(rawAim[0], rawAim[1], rawAim[2]);

    // aim up if they're on the same level as me and far away.
    if (dist > 512 && aimAdjusted[2] < 64 && aimAdjusted[2] > -64) {
      aimAdjusted[2] += dist - 512;
    }

    const normalized = vec3_normalized(aimAdjusted);
    pitch = normalized[2];
    if (pitch > 0.4) pitch = 0.4;
    else if (pitch < -0.5) pitch = -0.5;
  }

  let aim = vec3_add(forward, vec3_muls(right, spread));
  aim = vec3_add(aim, vec3_muls(up, pitch));

  // try search for best pitch
  if (M_CalculatePitchToFire(self, target, start, aim, 600, 2.5, false)) {
    monster_fire_grenade(self, start, aim, 50, 600, flash_number, crandom_open() * 10.0, frandom() * 10.0);
  } else {
    // normal shot
    monster_fire_grenade(self, start, aim, 50, 600, flash_number, crandom_open() * 10.0, 200.0 + crandom_open() * 10.0);
  }
}

