export const gunner_attack = RegisterMonsterinfoAttack("gunner_attack", (self: EdictT): void => {
  monster_done_dodge(self);

  if (self.enemy === null) return;

  // PMM
  if (self.monsterinfo.attack_state === MonsterAttackStateT.AS_BLIND) {
    if (self.timestamp > level.time) return;

    let chance: number;
    if (self.monsterinfo.blind_fire_delay < Gtime_from_sec(1)) chance = 1.0;
    else if (self.monsterinfo.blind_fire_delay < Gtime_from_sec(7.5)) chance = 0.4;
    else chance = 0.1;

    const r = frandom();

    // minimum of 4.1 seconds, plus 0-3, after the shots are done
    self.monsterinfo.blind_fire_delay = Gtime_add(Gtime_add(self.monsterinfo.blind_fire_delay, Gtime_from_ms(4100)), random_time(Gtime_from_sec(3)));

    // don't shoot at the origin
    if (self.monsterinfo.blind_fire_target[0] === 0 && self.monsterinfo.blind_fire_target[1] === 0 && self.monsterinfo.blind_fire_target[2] === 0) return;

    // don't shoot if the dice say not to
    if (r > chance) return;

    // turn on manual steering to signal both manual steering and blindfire
    self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_MANUAL_STEERING;

    if (gunner_grenade_check(self)) {
      M_SetAnimation(self, brandom() ? gunner_move_attack_grenade2 : gunner_move_attack_grenade, false);
      self.monsterinfo.attack_finished = Gtime_add(level.time, random_time(Gtime_from_sec(2)));
    } else {
      self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_MANUAL_STEERING;
    }

    self.timestamp = Gtime_add(level.time, random_time(Gtime_from_sec(2), Gtime_from_sec(3)));

    return;
  }

  // PGM - gunner needs to use his chaingun if he's being attacked by a tesla.
  if (
    self.bad_area ||
    self.timestamp > level.time ||
    (range_to(self, self.enemy) <= RANGE_NEAR * 0.35 && M_CheckClearShot(self, monsterFlashOffset()[MonsterMuzzleflashIdT.MZ2_GUNNER_MACHINEGUN_1] as Vec3))
  ) {
    M_SetAnimation(self, gunner_move_attack_chain, false);
  } else {
    if (self.timestamp <= level.time && frandom() <= 0.5 && gunner_grenade_check(self)) {
      M_SetAnimation(self, brandom() ? gunner_move_attack_grenade2 : gunner_move_attack_grenade, false);
      self.timestamp = Gtime_add(level.time, random_time(Gtime_from_sec(2), Gtime_from_sec(3)));
    } else if (M_CheckClearShot(self, monsterFlashOffset()[MonsterMuzzleflashIdT.MZ2_GUNNER_MACHINEGUN_1] as Vec3)) {
      M_SetAnimation(self, gunner_move_attack_chain, false);
    }
  }
});

function gunner_fire_chain(self: EdictT): void {
  M_SetAnimation(self, gunner_move_fire_chain, false);
}

function gunner_refire_chain(self: EdictT): void {
  if (self.enemy !== null && self.enemy.health > 0 && visible(self, self.enemy) && frandom() <= 0.5) {
    M_SetAnimation(self, gunner_move_fire_chain, false);
    return;
  }
  M_SetAnimation(self, gunner_move_endfire_chain, false);
}

// ---------------------------------------------------------------------------
// jumping (PGM)
// ---------------------------------------------------------------------------

function gunner_jump_now(self: EdictT): void {
  const { forward, up } = AngleVectors_destructured(self.s.angles);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 100));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 300));
}

function gunner_jump2_now(self: EdictT): void {
  const { forward, up } = AngleVectors_destructured(self.s.angles);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 150));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 400));
}

function monster_jump_finished(self: EdictT): boolean {
  const { forward } = AngleVectors_destructured(self.s.angles);
  const forward_velocity = vec3_muls(forward, vec3_dot(self.velocity, forward));

  if (vec3_length(forward_velocity) < 150) {
    const z_velocity = self.velocity[2];
    self.velocity = vec3_muls(forward, 150);
    self.velocity[2] = z_velocity;
  }

  return self.monsterinfo.jump_time < level.time;
}

function gunner_jump_wait_land(self: EdictT): void {
  if (self.groundentity === null) {
    self.monsterinfo.nextframe = self.s.frame;

    if (monster_jump_finished(self)) self.monsterinfo.nextframe = self.s.frame + 1;
  } else {
    self.monsterinfo.nextframe = self.s.frame + 1;
  }
}

const gunner_frames_jump: MframeT[] = [
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move, 0, gunner_jump_now),
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move, 0, gunner_jump_wait_land),
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move),
];
export const gunner_move_jump = RegisterMmove(
  "gunner_move_jump",
  Object.assign(new MmoveT(), { firstframe: FRAME_jump01, lastframe: FRAME_jump10, frame: gunner_frames_jump, endfunc: (self: EdictT) => gunner_run(self) }),
);

const gunner_frames_jump2: MframeT[] = [
  mkframe(ai_move, -8),
  mkframe(ai_move, -4),
  mkframe(ai_move, -4),
  mkframe(ai_move, 0, gunner_jump2_now),
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move, 0, gunner_jump_wait_land),
  mkframe(ai_move),
  mkframe(ai_move),
  mkframe(ai_move),
];
export const gunner_move_jump2 = RegisterMmove(
  "gunner_move_jump2",
  Object.assign(new MmoveT(), { firstframe: FRAME_jump01, lastframe: FRAME_jump10, frame: gunner_frames_jump2, endfunc: (self: EdictT) => gunner_run(self) }),
);

function gunner_jump(self: EdictT, result: BlockedJumpResultT): void {
  if (self.enemy === null) return;

  monster_done_dodge(self);

  if (result === BlockedJumpResultT.JUMP_JUMP_UP) {
    M_SetAnimation(self, gunner_move_jump2, false);
  } else {
    M_SetAnimation(self, gunner_move_jump, false);
  }
}

// ---------------------------------------------------------------------------
// blocked / duck / sidestep (PGM/PMM)
// ---------------------------------------------------------------------------

export const gunner_blocked = RegisterMonsterinfoBlocked("gunner_blocked", (self: EdictT, dist: number): boolean => {
  if (blocked_checkplat(self, dist)) return true;

  const result = blocked_checkjump(self, dist);
  if (result !== BlockedJumpResultT.NO_JUMP) {
    if (result !== BlockedJumpResultT.JUMP_TURN) gunner_jump(self, result);
    return true;
  }

  return false;
});

export const gunner_duck = RegisterMonsterinfoDuck("gunner_duck", (self: EdictT, _eta: GTime): boolean => {
  if (self.monsterinfo.active_move === gunner_move_jump2 || self.monsterinfo.active_move === gunner_move_jump) {
    return false;
  }

  if (
    self.monsterinfo.active_move === gunner_move_attack_chain ||
    self.monsterinfo.active_move === gunner_move_fire_chain ||
    self.monsterinfo.active_move === gunner_move_attack_grenade ||
    self.monsterinfo.active_move === gunner_move_attack_grenade2
  ) {
    // if we're shooting don't dodge
    if (self.monsterinfo.unduck !== null) self.monsterinfo.unduck(self);
    return false;
  }

  if (frandom() > 0.5) GunnerGrenade(self);

  M_SetAnimation(self, gunner_move_duck, false);

  return true;
});

export const gunner_sidestep = RegisterMonsterinfoSidestep("gunner_sidestep", (self: EdictT): boolean => {
  if (self.monsterinfo.active_move === gunner_move_jump2 || self.monsterinfo.active_move === gunner_move_jump || self.monsterinfo.active_move === gunner_move_pain1) {
    return false;
  }

  if (
    self.monsterinfo.active_move === gunner_move_attack_chain ||
    self.monsterinfo.active_move === gunner_move_fire_chain ||
    self.monsterinfo.active_move === gunner_move_attack_grenade ||
    self.monsterinfo.active_move === gunner_move_attack_grenade2
  ) {
    // if we're shooting, don't dodge
    return false;
  }

  if (self.monsterinfo.active_move !== gunner_move_run) M_SetAnimation(self, gunner_move_run, false);

  return true;
});

