const RANGE_NEAR = 440;
const SPAWNFLAG_GUNNER_NOJUMPING = 8;

/*QUAKED monster_gunner (1 .5 0) (-16 -16 -24) (16 16 32) Ambush Trigger_Spawn Sight NoJumping
model="models/monsters/gunner/tris.md2"
*/
export function SP_monster_gunner(self: EdictT): void {
  if (!M_AllowSpawn(self)) {
    G_FreeEdict(self);
    return;
  }

  assignSound(sound_death, "gunner/death1.wav");
  assignSound(sound_pain, "gunner/gunpain2.wav");
  assignSound(sound_pain2, "gunner/gunpain1.wav");
  assignSound(sound_idle, "gunner/gunidle1.wav");
  assignSound(sound_open, "gunner/gunatck1.wav");
  assignSound(sound_search, "gunner/gunsrch1.wav");
  assignSound(sound_sight, "gunner/sight1.wav");

  gi.soundindex("gunner/gunatck2.wav");
  gi.soundindex("gunner/gunatck3.wav");

  self.movetype = MovetypeT.MOVETYPE_STEP;
  self.solid = SolidT.SOLID_BBOX;
  self.s.modelindex = gi.modelindex("models/monsters/gunner/tris.md2");

  gi.modelindex("models/monsters/gunner/gibs/chest.md2");
  gi.modelindex("models/monsters/gunner/gibs/foot.md2");
  gi.modelindex("models/monsters/gunner/gibs/garm.md2");
  gi.modelindex("models/monsters/gunner/gibs/gun.md2");
  gi.modelindex("models/monsters/gunner/gibs/head.md2");

  self.mins = vec3(-16, -16, -24);
  self.maxs = vec3(16, 16, 36);

  self.health = Math.trunc(175 * st.health_multiplier);
  self.gib_health = -70;
  self.mass = 200;

  self.pain = gunner_pain;
  self.die = gunner_die;

  self.monsterinfo.stand = gunner_stand;
  self.monsterinfo.walk = gunner_walk;
  self.monsterinfo.run = gunner_run;
  // pmm
  self.monsterinfo.dodge = M_MonsterDodge;
  self.monsterinfo.duck = gunner_duck;
  self.monsterinfo.unduck = monster_duck_up;
  self.monsterinfo.sidestep = gunner_sidestep;
  self.monsterinfo.blocked = gunner_blocked; // PGM
  // pmm
  self.monsterinfo.attack = gunner_attack;
  self.monsterinfo.melee = null;
  self.monsterinfo.sight = gunner_sight;
  self.monsterinfo.search = gunner_search;
  self.monsterinfo.setskin = gunner_setskin;

  gi.linkentity(self);

  M_SetAnimation(self, gunner_move_stand, false);
  self.monsterinfo.scale = MODEL_SCALE;

  // PMM
  self.monsterinfo.blindfire = true;
  self.monsterinfo.can_jump = (self.spawnflags & SPAWNFLAG_GUNNER_NOJUMPING) === 0;
  self.monsterinfo.drop_height = 192;
  self.monsterinfo.jump_height = 40;

  walkmonster_start(self);
}
